def tandem_scan(seq, maxperiod=40, minunits=2):
    n = len(seq)
    hits = []
    for p in range(1, maxperiod+1):
        # greedy: find maximal runs where consecutive copies match consensus
        i = 0
        while i + p*minunits <= n:
            unit = seq[i:i+p]
            # count how many consecutive copies with small mismatch (allow exact first)
            cnt = 1
            j = i
            while j+p+p <= n and seq[j+p:j+2*p] == unit:
                cnt += 1
                j += p
            if cnt >= minunits:
                hits.append((i, j+p, p, cnt))
                i = j+p
            else:
                i += 1
    return hits

