def long_exact_repeats(seq, k=40):
    d = defaultdict(list)
    for i in range(len(seq)-k+1):
        d[seq[i:i+k]].append(i)
    out = []
    for kmer, pos in d.items():
        if len(pos) >= 2:
            out.append((kmer, pos))
