def hamming(a,b):
    return sum(1 for x,y in zip(a,b) if x!=y)

def scan(query, maxmm, seq):
    L=len(query)
    hits=[]
    for i in range(len(seq)-L+1):
        w=seq[i:i+L]
        h=hamming(query,w)
        if h<=maxmm:
            hits.append((i+1,h,w))
    return hits

