import random
random.seed(0)
seq = ""
with open("region.fasta") as f:
    for line in f:
        if not line.startswith(">"):
            seq += line.strip()

from collections import Counter
cnt = Counter(seq)
alphabet = list(cnt.keys())
weights = [cnt[c] for c in alphabet]

def max_orf(s):
    stops={"TAA","TAG","TGA"}
    best=0
    for f in range(3):
        start=None
        run=0
        for j in range(f,len(s)-2,3):
            cod=s[j:j+3]
            if cod in stops:
                if start is not None:
                    best=max(best,j+3-start)
                start=None;run=0
            else:
                run+=1
                if start is None and cod=="ATG":
                    start=j
        if start is not None:
            best=max(best,len(s)-start)
    return best

def max_orf_both(s):
    comp={"A":"T","T":"A","G":"C","C":"G"}
    r="".join(comp[c] for c in reversed(s))
    return max(max_orf(s),max_orf(r))

obs=max_orf_both(seq)
print("Observed longest ORF (either strand):", obs, "bp")

sims=[]
for _ in range(300):
